/** 
 * Creates the corresponding ChatRoomMemberPresenceChangeEvent and notifies all <tt>ChatRoomMemberMemberPresenceListener</tt>s that a ChatRoomMember has joined or left this <tt>ChatRoom</tt>.
 * @param member the <tt>ChatRoomMember</tt> that this event is about
 * @param actorMember a member that act in the event (for example the kickerin a member kicked event)
 * @param eventID the identifier of the event
 * @param eventReason the reason of the event
 */
public void fireMemberPresenceEvent(final ChatRoomMember member,final ChatRoomMember actorMember,final String eventID,final String eventReason){
  try {
    if (eventID == ChatRoomMemberPresenceChangeEvent.MEMBER_JOINED) {
      addChatRoomMember(member.getContactAddress(),member);
    }
   else {
      removeChatRoomMember(member.getContactAddress());
    }
  } catch (NullPointerException e) {
    LOGGER.error("Failed to process member presence event due to null parameter", e);
    return;
  }

  ChatRoomMemberPresenceChangeEvent evt;
  if (actorMember != null) {
    evt=new ChatRoomMemberPresenceChangeEvent(this,member,actorMember,eventID,eventReason);
  }
 else {
    evt=new ChatRoomMemberPresenceChangeEvent(this,member,eventID,eventReason);
  }

  if (LOGGER.isTraceEnabled()) {
    LOGGER.trace("Will dispatch the following ChatRoom event: " + evt);
  }

  Iterable<ChatRoomMemberPresenceListener> listeners;
  synchronized (memberListeners) {
    listeners=new ArrayList<ChatRoomMemberPresenceListener>(memberListeners);
  }

  for (ChatRoomMemberPresenceListener listener : listeners) {
    listener.memberPresenceChanged(evt);
  }
}
